const staticData = $getWorkflowStaticData('global');
staticData.rotationIndex = (staticData.rotationIndex || 0) + 1;

const cities = [
  'Austin, TX', 'Dallas, TX', 'Houston, TX', 'Miami, FL', 'Atlanta, GA',
  'Denver, CO', 'Chicago, IL', 'Phoenix, AZ', 'San Diego, CA', 'Tampa, FL',
  'Charlotte, NC', 'Nashville, TN'
];

const config = $('Config: VA Profile & Settings').first().json;
const role = config.va_role || 'Automation VA';

// 4 distinct categories combining niches via OR queries
const categoriesByRole = {
  'Automation VA': [
    {
      categoryName: 'Agency Partners & AAAs',
      query: 'AI Automation Agency OR Lead Generation Agency OR Web Design Agency OR Digital Marketing Agency',
      defaultCategory: 'AI Automation Agency',
      defaultPlural: 'digital and automation agencies',
      defaultPain: 'client workflow delivery and n8n overflow development'
    },
    {
      categoryName: 'High-Ticket Trade Contractors',
      query: 'Commercial Roofing Contractor OR Commercial HVAC Contractor OR Commercial Solar Contractor',
      defaultCategory: 'Commercial Roofing Contractor',
      defaultPlural: 'commercial contractors',
      defaultPain: 'job completion and review collection'
    },
    {
      categoryName: 'Real Estate & Property Management',
      query: 'Real Estate Agency OR Property Management Company',
      defaultCategory: 'Real Estate Agency',
      defaultPlural: 'real estate and property teams',
      defaultPain: 'property inquiries and tenant intake routing'
    },
    {
      categoryName: 'Professional & Financial Services',
      query: 'Commercial Law Firm OR CPA Accounting Firm OR Boutique Advisory Firm OR Staffing Agency OR Wealth Management Firm',
      defaultCategory: 'Commercial Law Firm',
      defaultPlural: 'professional practices',
      defaultPain: 'client intake routing and consultation document prep'
    }
  ],
  'Social Media Manager (SMM)': [
    {
      categoryName: 'Creative & Digital Studios',
      query: 'Creative Branding Studio OR Digital Marketing Agency',
      defaultCategory: 'Creative Branding Studio',
      defaultPlural: 'creative studios',
      defaultPain: 'client case studies and weekly visual content'
    },
    {
      categoryName: 'E-commerce Brands',
      query: 'E-commerce Brand OR Online Retailer',
      defaultCategory: 'E-commerce Brand',
      defaultPlural: 'e-commerce brands',
      defaultPain: 'product catalogs and organic social clips'
    }
  ],
  'Executive VA': [
    {
      categoryName: 'Advisory & Professional Services',
      query: 'Boutique Advisory Firm OR Commercial Law Firm OR Accounting Firm',
      defaultCategory: 'Boutique Advisory Firm',
      defaultPlural: 'consulting firms',
      defaultPain: 'executive calendar triage and consultation document coordination'
    }
  ],
  'General VA': [
    {
      categoryName: 'Local Contractors & Services',
      query: 'Commercial Roofing Contractor OR Property Management Company OR Dental Clinic',
      defaultCategory: 'Commercial Roofing Contractor',
      defaultPlural: 'service businesses',
      defaultPain: 'customer inquiry response and schedule coordination'
    }
  ]
};

const activeCategories = categoriesByRole[role] || categoriesByRole['Automation VA'];

// Combinatorial coverage across cities and the 4 categories
const totalCombinations = cities.length * activeCategories.length;
const currentStep = (staticData.rotationIndex - 1) % totalCombinations;
const catIndex = currentStep % activeCategories.length;
const cityIndex = Math.floor(currentStep / activeCategories.length) % cities.length;

const targetCity = cities[cityIndex];
const selectedCategory = activeCategories[catIndex];
const searchQuery = `${selectedCategory.query} in ${targetCity}`;

// Collect existing Place IDs from CRM and Suppression List to pass to scraper exclusion
let crmPlaceIds = [];
try {
  crmPlaceIds = $('Fetch Existing CRM Domains').all()
    .map(r => (r.json.fields && r.json.fields['Place ID']) || r.json['Place ID'])
    .filter(Boolean);
} catch (e) {}

let suppressedPlaceIds = [];
try {
  suppressedPlaceIds = $('Fetch Suppressed Domains').all()
    .map(r => (r.json.fields && r.json.fields['Place ID']) || r.json['Place ID'])
    .filter(Boolean);
} catch (e) {}

staticData.seenPlaceIds = staticData.seenPlaceIds || [];
const allPlaceIds = Array.from(new Set([...crmPlaceIds, ...suppressedPlaceIds, ...staticData.seenPlaceIds]));
// Pass the most recent 120 Place IDs so the URL stays compact and well within limits
const excludePlaceIdsParam = allPlaceIds.slice(-120).join(',');

return [{
  json: {
    ...config,
    search_query: searchQuery,
    target_city: targetCity,
    target_category: selectedCategory.defaultCategory,
    category_plural: selectedCategory.defaultPlural,
    base_pain_area: selectedCategory.defaultPain,
    category_name: selectedCategory.categoryName,
    exclude_place_ids: excludePlaceIdsParam,
    total_excluded_cached: allPlaceIds.length,
    rotation_index: staticData.rotationIndex,
    rotation_coverage: `${cityIndex + 1}/${cities.length} cities, ${catIndex + 1}/${activeCategories.length} categories (combo ${currentStep + 1}/${totalCombinations})`
  }
}];

