={{
  (() => {
  const raw = ($json.website || '').trim();
  if (!raw) return '';
  const host = raw.replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].split(':')[0].toLowerCase().trim().replace(/^www\./, '').replace(/\.$/, '');
  if (!host || !host.includes('.')) return '';
  const socialBlocklist = ['facebook.com', 'instagram.com', 'linkedin.com', 'twitter.com', 'x.com', 'linktr.ee', 'yelp.com', 'yellowpages.com', 'tripadvisor.com', 'tiktok.com', 'youtube.com', 'google.com', 'g.page', 'goo.gl', 'bit.ly'];
  if (socialBlocklist.some(s => host === s || host.endsWith('.' + s))) return '';
  // Website builders: keep the site's own subdomain (name.wixsite.com, name.squarespace.com) as the lead key;
  // a bare builder host with no site name is not usable.
  const builders = ['wixsite.com', 'squarespace.com', 'weebly.com', 'godaddysites.com', 'business.site', 'square.site', 'webflow.io', 'wordpress.com', 'carrd.co', 'jimdosite.com', 'mystrikingly.com', 'site123.me', 'editorx.io'];
  if (builders.includes(host)) return '';
  return host;
})()
}}

