parameters.jsCode:
const items = $input.all();
const staticData = $getWorkflowStaticData('global');

return items.map((item) => {
  const data = item.json;

  // Increment counters safely on successful assembly
  if (data.provider === 'openai') {
    if (data.lead_tier === 'Tier A') {
      staticData.tierAOpenAiDrafts = (staticData.tierAOpenAiDrafts || 0) + 1;
    } else {
      staticData.tierBOpenAiDrafts = (staticData.tierBOpenAiDrafts || 0) + 1;
    }
  } else if (data.provider === 'nvidia') {
    staticData.nemotronDraftsToday = (staticData.nemotronDraftsToday || 0) + 1;
    staticData.nemotronDraftsThisMonth = (staticData.nemotronDraftsThisMonth || 0) + 1;
  }
  const draft = data.draft || {};
  const bizName = data.clean_business_name || data.business_name || 'Business Partner';
  const greeting = data.greeting || `Hi ${bizName} team,`;
  const senderName = data.sender_name || 'Laurence Emmanuel Supangan';
  const senderFirst = data.sender_first || 'Laurence';
  const portfolioLink = data.portfolio_link || 'your-n8n.example.com';
  const physicalAddress = data.sender_physical_address || data.sender_location || '38 San Jose St., Brgy. San Antonio, Quezon City, Metro Manila 1105, Philippines';

  // Format email_1
  const email1Body = `${greeting}\n\n${draft.email_1}\n\n${senderName}\n${portfolioLink}\n${physicalAddress}\nIf this isn't relevant, reply "no" and I won't email again.`;

  // Format follow-ups (store clean body without signature, WF4 adds the single final signature block)
  const f1Body = (draft.followup_1 || '').replace(/\s*-\s*Laurence.*$/is, '').trim();
  const f2Body = (draft.followup_2 || '').replace(/\s*-\s*Laurence.*$/is, '').trim();
  const f3Body = (draft.followup_3 || '').replace(/\s*-\s*Laurence.*$/is, '').trim();

  // Enforce human-in-the-loop: all fresh drafts require approval in Discord deck
  const reviewStatus = 'Review Required';

  const hookEvidence = draft.hook_evidence || data.signal_fact || '';
  const proofUsed = draft.proof_used || data.proof_point || '';

  const notesWithScore = `${data.icp_score_breakdown || ''}\n[Email: ${data.extracted_email || 'None found'} (${data.email_type || 'none'}) | Domain: ${data.domain || ''}]\n[Chosen Signal: ${draft.chosen_signal || 'default'}]\n\nSubject: ${draft.subject}\n\n${email1Body}`;

  return {
    json: {
      ...data,
      business_name: bizName,
      subject_line: draft.subject || `workflow note for ${(bizName).toLowerCase()}`,
      email_1: email1Body,
      followup_1: f1Body,
      followup_2: f2Body,
      followup_3: f3Body,
      hook_evidence: hookEvidence,
      proof_used: proofUsed,
      review_status: reviewStatus,
      assembled_email: email1Body,
      airtable_notes: notesWithScore
    }
  };
});

// Airtable (CRM + Suppression, returnAll) is the single source of truth for "already handled".
// We no longer mark leads as seen in static data here: that happened before the draft and
// the Airtable write, so any failure (LLM rate limit, parser error, timeout) lost the lead forever.
const staticData = $getWorkflowStaticData('global');
// One-time purge of the old static lists so leads lost to past failed runs are retried.
staticData.seenPlaceIds = [];
staticData.seenDomains = [];

// 1. Active CRM domains (previously rejected leads may be retried)
let activeCrmDomains = new Set();
try {
  const atItems = $('Fetch Existing CRM Domains').all();
  for (const item of atItems) {
    const r = item.json;
    const revStatus = (r.fields?.['Review Status'] || r['Review Status'] || '').toLowerCase();
    const d = (r.fields?.Domain || r.Domain || r.fields?.domain || r.domain || '').toLowerCase().trim();
    if (d && revStatus !== 'rejected') {
      activeCrmDomains.add(d);
    }
  }
} catch (e) {}

// 2. Suppressed domains
let suppressedDomains = new Set();
try {
  const suppItems = $('Fetch Suppressed Domains').all();
  for (const item of suppItems) {
    const r = item.json;
    const d = (r.fields?.Domain || r.Domain || r.fields?.domain || r.domain || '').toLowerCase().trim();
    if (d) suppressedDomains.add(d);
  }
} catch (e) {}

const items = $input.all();
const freshItems = [];
const batchSeenDomains = new Set();
const batchSeenPlaceIds = new Set();

for (const item of items) {
  const pId = (item.json.place_id || '').trim();
  const rawDom = (item.json.domain || '').trim().toLowerCase();

  // A. Already in active CRM
  if (rawDom && activeCrmDomains.has(rawDom)) continue;
  // B. In Suppression list
  if (rawDom && suppressedDomains.has(rawDom)) continue;
  // C. Duplicate within this batch
  if (rawDom && batchSeenDomains.has(rawDom)) continue;
  if (pId && batchSeenPlaceIds.has(pId)) continue;

  if (pId) batchSeenPlaceIds.add(pId);
  if (rawDom) batchSeenDomains.add(rawDom);
  freshItems.push(item);
}

return freshItems;

const lead = $json;
const cfg = $('Config: VA Profile & Settings').first().json;
const city = lead.target_city || '';
const spelling = /UK|London|Manchester|Australia|Sydney|Melbourne|Brisbane/.test(city)
  ? 'British/Australian (enquiries, organisation, centre)'
  : /Canada|Toronto|Vancouver/.test(city) ? 'Canadian (organization, centre)'
  : 'American (inquiries, organization, center)';

// Title & Role
const professionalTitle = 'workflow automation specialist';
const article = 'a';

let proofs = [];
try { proofs = JSON.parse(cfg.proof_points || '[]'); } catch (e) { proofs = []; }

// Match category and signal
const cat = (lead.target_category || '').toLowerCase();
let categoryKey = 'contractor';
if (/staffing|recruit/i.test(cat)) categoryKey = 'staffing';
else if (/property management|hoa/i.test(cat)) categoryKey = 'propertymgmt';
else if (/roofing|contractor|construction|hvac|solar|plumb/i.test(cat)) categoryKey = 'contractor';
else if (/real estate|property|realtor|broker/i.test(cat)) categoryKey = 'realestate';
else if (/ai automation|ai agency/i.test(cat)) categoryKey = 'aaa';
else if (/agency|marketing|digital|creative|seo|branding|web/i.test(cat)) categoryKey = 'agency';
else if (/law|legal|attorney/i.test(cat)) categoryKey = 'legal';
else if (/accounting|cpa|bookkeep/i.test(cat)) categoryKey = 'accounting';
else if (/wealth|financial|advis/i.test(cat)) categoryKey = 'advisory';

let matchingPool = proofs.filter(p => p.categories && p.categories.includes(categoryKey));

// Adjacent examples for Proof Paragraph
let adjacentSteps = 'The same setup works for lead intake, CRM updates, and scheduling handoffs.';
let focusArea = 'inquiry follow-up';

if (categoryKey === 'contractor') {
  adjacentSteps = 'The same setup works for service dispatching, quote follow-ups, and job-completion invoicing.';
  focusArea = 'review follow-up';
} else if (categoryKey === 'realestate') {
  adjacentSteps = 'The same setup works for new portal inquiries, showing requests, and CRM status updates.';
  focusArea = 'property inquiry routing';
} else if (categoryKey === 'agency' || categoryKey === 'aaa') {
  adjacentSteps = 'The same setup works for client onboarding, webhook handoffs, and project board creation.';
  focusArea = 'client onboarding';
} else if (categoryKey === 'legal' || categoryKey === 'accounting') {
  adjacentSteps = 'The same setup works for document collection, intake form triage, and calendar scheduling.';
  focusArea = 'consultation intake';
}

if (matchingPool.length === 0) matchingPool = proofs;

// Format proofs for LLM menu
const proofOptionsFormatted = matchingPool.map((p, idx) => `[Option ${idx + 1}] ${p.text}`).join('\n');

// Format detected signals menu for LLM
const signals = lead.detected_signals || [];
const signalsMenuFormatted = signals.map((s, idx) => `${idx + 1}. [${s.key}] ${s.fact}`).join('\n');

// Claude-refined Dual-Path CTA
const refinedCta = `I'd be glad to map out and build a working sample of that for your setup for free, no call needed. If ${focusArea} isn't your main bottleneck, tell me what is and I'll build a small sample for that instead. Just let me know what tools your team uses and I'll send over a video demo. If it helps, we can talk. If not, no worries.`;

let samples = [];
try { samples = JSON.parse(cfg.writing_samples || '[]'); } catch (e) { samples = []; }
const picked = samples.sort(() => Math.random() - 0.5).slice(0, 2).join('\n---\n');

const cleanName = lead.clean_business_name || lead.business_name || '';

let greeting = `Hi ${cleanName} team,`;
if (cleanName && cleanName.split(' ').length > 3) {
  greeting = 'Hi there,';
}

// Use a first name only when the address is clearly a person's at the company's own domain
// (first.last@ or first_last@). Webmail usernames (you@example.com) and run-together handles
// (jsmith@) would read badly, so those keep the team greeting.
if (lead.extracted_email && lead.email_type === 'direct') {
  const userPart = lead.extracted_email.split('@')[0].toLowerCase();
  const m = userPart.match(/^([a-z]{3,15})[._-][a-z]{2,20}$/);
  if (m) greeting = `Hi ${m[1].charAt(0).toUpperCase() + m[1].slice(1)},`;
}

return {
  json: {
    ...lead,
    clean_business_name: cleanName,
    professional_title: professionalTitle,
    title_with_article: `${article} ${professionalTitle}`,
    spelling,
    signals_menu: signalsMenuFormatted,
    proof_options: proofOptionsFormatted,
    proof_point: matchingPool[0]?.text || '',
    adjacent_steps: adjacentSteps,
    focus_area: focusArea,
    cta: refinedCta,
    picked_samples: picked,
    voice_notes: cfg.voice_notes || '',
    greeting,
    sender_first: (lead.sender_name || 'Laurence').split(' ')[0]
  }
};

// Validate & Clean Draft (v2, 2026-11-12)
// 1. Clean deterministically: dashes, "!", emojis, stray greetings/sign-offs, banned words -> plain swaps.
// 2. Check each field on its own. A bad follow-up or subject is swapped for the safe template version;
//    only a bad email_1 (the personalised part) sends the whole draft to the template.
// 3. If this is the first pass and email_1 still fails, set needs_repair so the workflow can ask the LLM once more.
const out = $json.output || $json;
// Repair pass = this item went through 'Prepare Repair Prompt' before the LLM (its input carries repair_note).
let isRepairPass = Boolean($json.repair_pass);
try { isRepairPass = isRepairPass || Boolean($('If: Provider is OpenAI?').item.json.repair_note); } catch (e) {}

let lead = {};
try { lead = $('Prepare Writing Inputs').item.json; } catch (e) {
  try { lead = $('Prepare Writing Inputs').itemMatching($itemIndex).json; } catch (e2) {
    try { lead = $('Prepare Writing Inputs').first().json || {}; } catch (e3) { lead = {}; }
  }
}

const wc = s => (s || '').trim().split(/\s+/).filter(Boolean).length;
const LIMITS = { email_1: [70, 185], followup_1: [30, 85], followup_2: [20, 70], followup_3: [15, 55] };
const BODY = ['email_1', 'followup_1', 'followup_2', 'followup_3'];

// Banned phrase -> safe replacement. Inflections are covered; "a/an" before a swapped adjective is fixed.
const SWAPS = [
  [/\b(an?\s+)?impressive(ly)?\b/gi, (m, a, ly) => (a ? 'a ' : '') + (ly ? 'clearly' : 'solid')],
  [/\b(an?\s+)?amazing(ly)?\b/gi, (m, a, ly) => (a ? 'a ' : '') + (ly ? 'very' : 'strong')],
  [/\b(an?\s+)?great(ly)?\b/gi, (m, a, ly) => (a ? 'a ' : '') + (ly ? 'a lot' : 'good')],
  [/\bi'?d love to\b/gi, "I'd like to"], [/\bwould love to\b/gi, 'would like to'],
  [/\blov(e|es|ed|ing)\b/gi, (m, s) => ({ e: 'like', es: 'likes', ed: 'liked', ing: 'liking' })[s.toLowerCase()]],
  [/\bpassionate(ly)?\b/gi, (m, ly) => ly ? 'closely' : 'focused'],
  [/\bstreamlin(e|es|ed|ing)\b/gi, (m, s) => ({ e: 'simplify', es: 'simplifies', ed: 'simplified', ing: 'simplifying' })[s.toLowerCase()]],
  [/\bleverag(e|es|ed|ing)\b/gi, (m, s) => ({ e: 'use', es: 'uses', ed: 'used', ing: 'using' })[s.toLowerCase()]],
  [/\b(an?\s+)?game[- ]changers?\b/gi, (m, a) => (a ? 'a ' : '') + 'real help'],
  [/\bcutting[- ]edge\b/gi, 'modern'],
  [/\bsolutions\b/gi, 'systems'],
  [/\bsynerg(y|ies)\b/gi, 'fit'],
  [/[^.?\n]*\bhope this (email |note |message )?finds you[^.?\n]*[.?]?\s*/gi, ''],
  [/\breaching out\b/gi, 'writing'],
  [/\btouch(ing)? base\b/gi, (m, ing) => ing ? 'talking' : 'talk'],
  [/\bjust checking in\b/gi, 'a quick note'],
  [/\bcircl(e|ing) back\b/gi, (m, s) => s.toLowerCase() === 'e' ? 'come back' : 'coming back'],
  [/\bfollowing up\b/gi, 'writing again'],
];
const BANNED_RX = [
  /\bimpressive/i, /\bamazing/i, /\bgreat(ly)?\b/i, /\blov(e|es|ed|ing)\b/i, /\bpassionate/i,
  /\bstreamlin/i, /\bleverag/i, /\bgame[- ]changer/i, /\bcutting[- ]edge\b/i, /\bsolutions\b/i,
  /\bsynerg/i, /\bhope this .{0,10}finds\b/i, /\breaching out\b/i, /\btouch(ing)? base\b/i,
  /\bjust checking in\b/i, /\bcircl(e|ing) back\b/i, /\bfollowing up\b/i,
];

function cleanBody(s) {
  let t = String(s || '').replace(/\r/g, '');
  t = t.replace(/^\s*subject:.*\n+/i, '');                                   // stray subject line
  t = t.replace(/^\s*(hi|hello|hey|dear)\b[^\n]{0,60}\n+/i, '');            // greeting (Assemble adds its own)
  t = t.replace(/\n+\s*(best|best regards|kind regards|regards|thanks|thank you|cheers|sincerely|warmly)\b[^\n]{0,40}(\n[^\n]{0,60}){0,3}\s*$/i, ''); // sign-off block
  t = t.replace(/\n+\s*-?\s*laurence[^\n]{0,60}\s*$/i, '');                  // bare name sign-off
  t = t.replace(/\s*[—–]\s*/g, ', ').replace(/!/g, '.');
  t = t.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '');
  for (const [rx, rep] of SWAPS) t = t.replace(rx, rep);
  t = t.replace(/[ \t]{2,}/g, ' ').replace(/ +([,.?])/g, '$1').replace(/,\s*,/g, ',').replace(/\.{2,}/g, '.');
  t = t.replace(/(^|[.?]\s+|\n)([a-z])/g, (m, p, c) => p + c.toUpperCase());   // sentence case after a removed clause
  return t.split('\n').map(l => l.trim()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
function cleanSubject(s) {
  let t = String(s || '').replace(/^\s*subject:\s*/i, '').replace(/["'`]/g, '');
  t = t.replace(/\s*[—–]\s*/g, ' ').replace(/[!?.]+$/g, '').replace(/!/g, '');
  for (const [rx, rep] of SWAPS) t = t.replace(rx, rep);
  return t.toLowerCase().replace(/\s{2,}/g, ' ').trim();
}

const biz = lead.clean_business_name || lead.business_name || 'your team';
const city = lead.target_city || 'your area';
const TEMPLATE = {
  chosen_signal: lead.signal_type || lead.chosen_signal || 'local_presence',
  hook_evidence: lead.signal_fact || `${biz} is based in ${city}.`,
  proof_used: lead.proof_point || 'built back-office automations in n8n that eliminate manual data entry between forms, CRMs, and team communication tools',
  subject: `workflow note for ${biz.toLowerCase()}`,
  email_1: `I was looking into ${biz} in ${city} and noticed your strong presence on Google. With professional teams handling steady inbound inquiries, I was curious: how does your staff currently manage the handoff between new client inquiries and scheduling consultations?\n\nI'm ${lead.sender_first || 'Laurence'}, an automation specialist based in Manila. I build custom n8n workflows that eliminate repetitive admin around intake triage, calendar bookings, and CRM updates.\n\nI'd be glad to map out and build a working sample for your setup for free. No call needed first. Just let me know what tools your team uses and I'll send over a video demo. If it helps, we can talk. If not, no worries.`,
  followup_1: `One quick note on this: the sample pipeline I map out connects your intake forms directly into your CRM and alerts your team without manual data entry.\n\nJust drop the names of 2 or 3 tools your team uses, and I will build the working demo for you.`,
  followup_2: `Quick question on this: is client intake and calendar scheduling something your operations manager already has completely handled in-house?\n\nIf that process is already covered smoothly on your end, just let me know and I will gladly drop it. If not, the free working sample offer still stands.`,
  followup_3: `Final note from me on this. If the timing is not right or your team is focused on other priorities, no worries at all.\n\nIf you ever want to eliminate manual handoffs between your forms, CRM, and calendars in the future, the offer stands.`,
};

const draft = {};
const fieldErrors = {};          // field -> [reasons]
const addErr = (k, msg) => { (fieldErrors[k] = fieldErrors[k] || []).push(msg); };

// Metadata: fill from the lead rather than failing the draft.
for (const k of ['chosen_signal', 'hook_evidence', 'proof_used']) {
  draft[k] = typeof out[k] === 'string' && out[k].trim() ? out[k].trim() : TEMPLATE[k];
}

draft.subject = cleanSubject(out.subject);
const sw = wc(draft.subject);
if (!draft.subject) addErr('subject', 'missing');
else if (sw < 3 || sw > 8) addErr('subject', `${sw} words, must be 3-8`);

for (const k of BODY) {
  if (typeof out[k] !== 'string' || !out[k].trim()) { addErr(k, 'missing'); draft[k] = ''; continue; }
  draft[k] = cleanBody(out[k]);
  const [lo, hi] = LIMITS[k];
  const n = wc(draft[k]);
  if (n < lo || n > hi) addErr(k, `${n} words, must be ${lo}-${hi}`);
}
for (const k of ['subject', ...BODY]) {
  for (const rx of BANNED_RX) if (draft[k] && rx.test(draft[k])) addErr(k, `banned phrase left: ${rx.source}`);
  if (draft[k] && /\b(virtual assistant|\bVA\b)/.test(draft[k])) addErr(k, 'says virtual assistant/VA');
}

const errors = Object.entries(fieldErrors).flatMap(([k, v]) => v.map(m => `${k}: ${m}`));
const email1Ok = !fieldErrors.email_1;
const fieldsReplaced = [];
let usedTemplate = false;
let needsRepair = false;

if (!email1Ok && !isRepairPass) {
  needsRepair = true;             // first pass: let the workflow ask the LLM to fix it once
} else if (!email1Ok) {
  usedTemplate = true;            // repair pass also failed: whole safe template
  Object.assign(draft, TEMPLATE);
} else {
  for (const k of ['subject', 'followup_1', 'followup_2', 'followup_3']) {
    if (fieldErrors[k]) { draft[k] = TEMPLATE[k]; fieldsReplaced.push(k); }
  }
}

return {
  json: {
    ...lead,
    draft,
    valid: email1Ok,                                  // the personalised email survived
    fully_valid: errors.length === 0,                 // nothing had to be swapped
    used_template: usedTemplate,
    fields_replaced: fieldsReplaced,
    needs_repair: needsRepair,
    repair_pass: isRepairPass,
    repair_errors: needsRepair ? errors.join('\n') : '',
    rejected_output: needsRepair ? out : undefined,
    needs_review: Boolean(usedTemplate || lead.needs_review),
    clean_errors: errors,
  },
};

const items = $input.all();

const HOOK = {
  booking_flow: 20,
  intake_form: 18,
  tech_crm: 16,
  team_hiring: 14,
  high_rating: 8,
  review_scale: 8,
  review_volume: 6,
  established_team: 4,
  office_presence: 4,
  local_presence: 0
};

return items.map(item => {
  const d = item.json;
  const draft = d.draft || {};
  const chosen = draft.chosen_signal || d.chosen_signal || d.signal_type || 'local_presence';

  let p = (d.icp_score || 0) * 0.35; // fit, 0-35
  const emailScores = { direct: 20, generic: 8, external: 2 };
  p += emailScores[d.email_type] ?? 8;
  p += HOOK[chosen] ?? 0;
  p += (d.has_mail_server || d.mx_valid) ? 5 : 0;

  if (d.needs_review) p -= 15;
  if (/Canada|Australia/i.test(d.target_city || '')) p -= 15;
  if ((Number(d.reviews_count) || 0) > 500) p -= 10;

  const sendPriority = Math.max(0, Math.min(100, Math.round(p)));

  // Universal Human-in-the-Loop Gate:
  // ALL fresh drafts require operator approval in Discord deck before sending.
  const status = 'Review Required';

  return {
    json: {
      ...d,
      send_priority: sendPriority,
      review_status: status
    }
  };
});

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const currentMonth = today.slice(0, 7); // e.g. '2026-11'

// Reset daily counters on new day
if (staticData.draftDate !== today) {
  staticData.draftDate = today;
  staticData.tierAOpenAiDrafts = 0;
  staticData.tierBOpenAiDrafts = 0;
  staticData.nemotronDraftsToday = 0;
}

// Reset monthly counters on new month
if (staticData.draftMonth !== currentMonth) {
  staticData.draftMonth = currentMonth;
  staticData.nemotronDraftsThisMonth = 0;
}

const items = $input.all();
const out = [];

// HARD SAFEGUARDS FOR OPENAI & NVIDIA NIM
const MAX_OPENAI_TIER_A_DAILY = 25;
const MAX_OPENAI_TIER_B_DAILY = 20;
const MAX_NEMOTRON_DAILY = 15;        // Daily pacing safeguard for NVIDIA NIM
const MAX_NEMOTRON_MONTHLY = 300;     // Monthly hard credit cap for NVIDIA NIM

for (const item of items) {
  const lead = item.json;
  const score = Number(lead.icp_score || 0);
  const isTierA = score >= 80;
  const isTierB = score >= 65 && score < 80;

  const nemotronAvailable = (staticData.nemotronDraftsToday || 0) < MAX_NEMOTRON_DAILY &&
                            (staticData.nemotronDraftsThisMonth || 0) < MAX_NEMOTRON_MONTHLY;

  if (isTierA) {
    if ((staticData.tierAOpenAiDrafts || 0) < MAX_OPENAI_TIER_A_DAILY) {
      // checked against limit
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier A',
          provider: 'openai',
          model_name: 'gpt-6-luna',
          should_draft: true,
          daily_draft_number: staticData.tierAOpenAiDrafts
        }
      });
    } else if (nemotronAvailable) {
      // checked against limit
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier A',
          provider: 'nvidia',
          model_name: 'nvidia/nemotron-3.5-bolt-e4b',
          should_draft: true,
          daily_draft_number: staticData.nemotronDraftsToday,
          nemotron_monthly_count: staticData.nemotronDraftsThisMonth
        }
      });
    } else {
      const reason = (staticData.nemotronDraftsThisMonth || 0) >= MAX_NEMOTRON_MONTHLY
        ? 'NVIDIA NIM monthly safety cap (300) reached'
        : 'Tier A daily caps reached (25 OpenAI + 15 Nemotron)';
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier A',
          should_draft: false,
          review_status: 'Backlog / Unassigned',
          backlog_reason: reason
        }
      });
    }
  } else if (isTierB) {
    if ((staticData.tierBOpenAiDrafts || 0) < MAX_OPENAI_TIER_B_DAILY) {
      // checked against limit
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier B',
          provider: 'openai',
          model_name: 'gpt-6-luna',
          should_draft: true,
          daily_draft_number: staticData.tierBOpenAiDrafts
        }
      });
    } else if (nemotronAvailable) {
      // Automatic switchover: Tier B drafts 21+ route to NVIDIA Nemotron within strict daily & monthly limits
      // checked against limit
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier B',
          provider: 'nvidia',
          model_name: 'nvidia/nemotron-3.5-bolt-e4b',
          should_draft: true,
          daily_draft_number: staticData.nemotronDraftsToday,
          nemotron_monthly_count: staticData.nemotronDraftsThisMonth
        }
      });
    } else {
      const reason = (staticData.nemotronDraftsThisMonth || 0) >= MAX_NEMOTRON_MONTHLY
        ? 'NVIDIA NIM monthly safety cap (300) reached'
        : 'Tier B daily caps reached (20 OpenAI + 15 Nemotron)';
      out.push({
        json: {
          ...lead,
          lead_tier: 'Tier B',
          should_draft: false,
          review_status: 'Backlog / Unassigned',
          backlog_reason: reason
        }
      });
    }
  } else {
    out.push({
      json: {
        ...lead,
        lead_tier: 'Disqualified',
        should_draft: false,
        review_status: 'Backlog / Unassigned',
        backlog_reason: `Low ICP fit (${score} < 65)`
      }
    });
  }
}

return out;

